  class Failure < StandardError; end

  class Probe
    def initialize(binary:, helper:, evidence_root:, generated_matrix:)
      @binary = validate_executable(binary, 'pinned ClickHouse')
      @helper = helper && validate_executable(helper, 'prebuilt W269 helper')
      @generated_matrix = generated_matrix
      fail!('--generated-matrix requires --crystal-helper') if @generated_matrix && !@helper
      @root = validate_root(evidence_root)
      @invocations = []
      @token = Digest::SHA256.hexdigest(@root)[0, 8]
      @source_files = [__FILE__, W241_SOURCE, FIXTURE_SOURCE]
      @source_files << File.realpath(HELPER_SOURCE) if @helper
      @source_files = @source_files.map { |path| File.realpath(path) }
      @runner = W241::Probe.allocate
      @runner.instance_variable_set(:@binary, @binary)
      @runner.instance_variable_set(:@root, @root)
      @runner.instance_variable_set(:@invocations, @invocations)
      @stock = {}
      validate_literal_column_keys!
    end

    def run
      validate_native_label_plan!
      prepare!
      %w[map map_with_buckets].each do |layout|
        %w[basic compact].each do |mode|
          key = cell_key('mrk4', layout, mode)
          @stock[key] = capture_stock!(layout, mode)
        end
      end
      audit_stock_captures! if @helper
      generated = @generated_matrix ? capture_generated_matrix! : nil
      mutant = generated ? qualify_copy_mutant!(generated.fetch(cell_key('mrk4', 'map_with_buckets', 'compact'))) : nil
      validate_pins!
      status = generated ? 'stock_oracle_generated_matrix_and_resealed_copy_mutant_captured' : 'stock_native_only_captured'
      summary = {
        format: FORMAT, status: status,
        runtime: {path: @binary, sha256: BINARY_SHA256, version: W241::VERSION, build: W241::BUILD,
                  sha256_before: @binary_sha_before, sha256_after: binary_sha},
        source_revision: {path: SOURCE_ROOT, revision: SOURCE_REVISION, files: @source_hashes_before},
        fixture: {schema: SCHEMA, rows: ROWS, native_windows: NATIVE_WINDOWS, local_windows: LOCAL_WINDOWS,
                  physical_marks: MARK_ROWS_WITH_EOF,
                  required_empty_array_mark: {column: 'array_json', pks: [3, 4]},
                  first_insert_census: census_report},
        metadata_contract: {serialization_info_version: 'with_types', string_version: 0,
                            propagate_types_serialization_versions_to_nested_types: true,
                            object_json_dynamic_version_entries: 'none'},
        stock_native_mrk4: @stock, generated_matrix: generated, resealed_middle_structure_mutant: mutant,
        invocations: @invocations, evidence_root: @root,
        claim_boundary: 'All four native stock rosters and literal SQL windows are captured before any candidate helper inspection. Empty native SQL is cardinality-only; helper last_mark is the separate two-row physical mark. CHECK is distinct from value SELECTs and is not a semantic oracle. Same-column mutant controls are observations, not locality claims; whole marks and EOF are audited, with no granule-only IO claim.',
      }
      write_new(File.join(@root, 'summary.json'), JSON.pretty_generate(summary) + "\n")
      write_new(File.join(@root, 'summary.md'), render_summary(summary))
      puts "W269 status=#{status}; stock=4; generated=#{generated ? 8 : 0}; evidence=#{@root}"
      true
    rescue StandardError => error
      @fatal_error ||= "#{error.class}: #{error.message}"
      persist_inconclusive(error)
      warn "W269 Compact JSON probe inconclusive: #{@fatal_error}"
      false
    end

    private

    def fail!(message)
      raise Failure, "W269: #{message}"
    end

    def validate_root(path)
      fail!('evidence root must be an existing empty direct child of /private/tmp') unless path && File.directory?(File.expand_path(path))
      expanded = File.expand_path(path)
      fail!('evidence root must be a direct child of /private/tmp') unless File.dirname(expanded) == File.realpath('/private/tmp')
      fail!('evidence root must be canonical, non-symlinked, and empty') unless
        !File.symlink?(expanded) && File.realpath(expanded) == expanded && Dir.children(expanded).empty?
      expanded
    rescue Errno::ENOENT
      fail!('evidence root or /private/tmp is absent')
    end

    def validate_executable(path, label)
      fail!("#{label} is absent, non-executable, or symlinked") unless path && File.file?(File.expand_path(path)) &&
        File.executable?(File.expand_path(path)) && !File.symlink?(File.expand_path(path))
      File.realpath(path)
    end

    def prepare!
      %w[invocations stores parts source-inventories raw-records].each { |name| Dir.mkdir(File.join(@root, name), 0o700) }
      @binary_sha_before = binary_sha
      fail!('ClickHouse executable differs from the W269 native pin') unless @binary_sha_before == BINARY_SHA256
      source_revision, source_stderr, source_status = Open3.capture3('git', '-C', SOURCE_ROOT, 'rev-parse', 'HEAD')
      fail!("pinned source revision check failed: #{source_stderr.strip}") unless source_status.success? && source_revision.strip == SOURCE_REVISION
      @helper_sha_before = helper_sha if @helper
      @source_hashes_before = @source_files.to_h { |path| [path, sha(path)] }
      @upstream_hashes = SOURCE_RELATIVE_FILES.to_h do |relative|
        path = File.join(SOURCE_ROOT, relative)
        fail!("pinned source file is absent: #{relative}") unless File.file?(path) && !File.symlink?(path)
        [relative, sha(path)]
      end
    end

    def binary_sha
      Digest::SHA256.file(@binary).hexdigest
    end

    def helper_sha
      Digest::SHA256.file(@helper).hexdigest
    end

    def sha(path)
      Digest::SHA256.file(path).hexdigest
    end

    def write_new(path, bytes)
      File.open(path, File::WRONLY | File::CREAT | File::EXCL, 0o600) { |file| file.write(bytes) }
    end

    def pin_sql
      @runner.send(:pin_sql)
    end

    def native(label, store, sql, allow_server_error: false)
      result = @runner.send(:native, label, store, [pin_sql, sql].join("\n"))
      record = result.fetch(:record)
      fail!("#{label} timed out or had process infrastructure failure") unless
        !record[:timed_out] && record[:spawn_error].nil? && record[:stdin_write_error].nil? &&
        record[:stdout_read_error].nil? && record[:stderr_read_error].nil? && result[:status] && result[:status].termsig.nil?
      accepted = allow_server_error ? %w[success server_exception] : ['success']
      fail!("#{label} native process classification #{result[:classification]} is outside #{accepted.inspect}") unless accepted.include?(result[:classification])
      if result[:classification] == 'success'
        @runner.send(:assert_native_success!, result, label)
        @runner.send(:assert_pin!, result[:stdout], label)
      else
        fail!("#{label} native executable identity changed") unless record[:binary_sha_after] == BINARY_SHA256
      end
      result
    end

    def native_lines(result, label)
      output = result[:stdout].dup.force_encoding(Encoding::UTF_8)
      fail!("#{label} output is not valid newline-terminated UTF-8") unless output.valid_encoding? && output.end_with?("\n")
      output.lines.map(&:chomp)
    end

    def settings(layout, mode, mark_format: 'mrk4')
      buckets = layout == 'map' ? 1 : 2
      layout_value = layout == 'map' ? 'map' : 'map_with_buckets'
      discriminator = mode == 'compact' ? 1 : 0
      substream_marks = mark_format == 'mrk4' ? 1 : 0
      [
        'index_granularity=2', 'index_granularity_bytes=10485760', 'enable_mixed_granularity_parts=1',
        'min_rows_for_wide_part=1000000', 'min_bytes_for_wide_part=104857600', 'min_level_for_wide_part=0',
        'compress_marks=0', 'compress_primary_key=0', 'write_final_mark=1',
        "write_marks_for_substreams_in_compact_parts=#{substream_marks}",
        'min_compress_block_size=0', 'max_compress_block_size=4096',
        'ratio_of_defaults_for_sparse_serialization=1.0', "default_compression_codec='LZ4'",
        "serialization_info_version='with_types'", 'propagate_types_serialization_versions_to_nested_types=true',
        "string_serialization_version='single_stream'", "object_serialization_version='v3'",
        "object_shared_data_serialization_version='#{layout_value}'",
        "object_shared_data_serialization_version_for_zero_level_parts='#{layout_value}'",
        "object_shared_data_buckets_for_compact_part=#{buckets}",
        "dynamic_serialization_version='v3'", "use_compact_variant_discriminators_serialization=#{discriminator}",
        'allow_suspicious_low_cardinality_types=1',
      ].join(', ')
    end

    def declarations
      SCHEMA.map { |name, type| "`#{name}` #{type}" }.join(', ')
    end

    def sql_string(value)
      "'#{value.to_s.gsub(/[\\']/) { |character| "\\#{character}" }}'"
    end

    def cast_doc(document)
      "CAST(#{sql_string(JSON.generate(document))}, #{sql_string(JSON_TYPE)})"
    end

    def sql_row(row)
      array = "CAST([#{row.fetch(:array_json).map { |document| cast_doc(document) }.join(', ')}], #{sql_string("Array(#{JSON_TYPE})")})"
      tagged_items = row.fetch(:tagged_json).map do |item|
        "(#{cast_doc(item.fetch(:doc))}, toUInt8(#{item.fetch(:tag)}))"
      end.join(', ')
      tagged_type = "Array(Tuple(doc #{JSON_TYPE}, tag UInt8))"
      tagged = "CAST([#{tagged_items}], #{sql_string(tagged_type)})"
      pair = row.fetch(:pair_json)
      pair_type = "Tuple(left #{JSON_TYPE}, right #{JSON_TYPE})"
      pair_expr = "tuple(#{cast_doc(pair.fetch(:left))}, #{cast_doc(pair.fetch(:right))})"
      "(toUInt64(#{row.fetch(:pk)}), #{cast_doc(row.fetch(:root_json))}, #{array}, #{tagged}, CAST(#{pair_expr}, #{sql_string(pair_type)}))"
    end

    def table_name(key, phase)
      "w269_#{@token}_#{key}_#{phase}"
    end

    def store_path(key)
      path = File.join(@root, 'stores', key)
      Dir.mkdir(path, 0o700) unless Dir.exist?(path)
      path
    end

    def marker(kind, key, window = nil)
      value = "__W269_#{kind.upcase}_#{key.upcase}"
      value += "_#{window.upcase}" if window
      "#{value}__"
    end

    def insert_sql(table)
      values = ROWS.map { |row| sql_row(row) }
      "INSERT INTO default.#{table} VALUES\n#{values.join(",\n")};\n"
    end

    def stock_sql(layout, mode, table)
      "SET flatten_nested=0;\nSET allow_suspicious_low_cardinality_types=1;\n" \
        "CREATE TABLE default.#{table} (#{declarations}) ENGINE=MergeTree ORDER BY pk SETTINGS #{settings(layout, mode)};\n" +
        insert_sql(table)
    end

    def select_projection(fields)
      result = ["'#{fields.fetch(:marker)}'", 'toString(pk)']
      result << 'hex(toJSONString(root_json))' if fields.fetch(:root, false)
      result << 'hex(toJSONString(array_json))' if fields.fetch(:array, false)
      if fields.fetch(:tagged, false)
        result << "hex(toJSONString(arrayMap(x -> tupleElement(x, 'doc'), tagged_json)))"
        result << "hex(toJSONString(arrayMap(x -> tupleElement(x, 'tag'), tagged_json)))"
      end
      if fields.fetch(:pair, false)
        result << "hex(toJSONString(tupleElement(pair_json, 'left')))"
        result << "hex(toJSONString(tupleElement(pair_json, 'right')))"
      end
      result.join(', ')
    end

    def native_window_sql(table, window, fields: {root: true, array: true, tagged: true, pair: true})
      id = fields.fetch(:case_name)
      marker_value = marker('native', id, window)
      predicate = WINDOW_PREDICATES.fetch(window)
      return "SELECT '#{marker_value}', toString(count()) FROM default.#{table} WHERE #{predicate} FORMAT TSVRaw;\n" if window == 'empty'
      projection = select_projection(fields.merge(marker: marker_value))
      "SELECT #{projection} FROM default.#{table} WHERE #{predicate} ORDER BY pk SETTINGS output_format_json_quote_64bit_integers=0 FORMAT TSVRaw;\n"
    end

    def tagged(lines, tag, width)
      lines.select { |line| line.start_with?(tag + "\t") }.map do |line|
        fields = line.split("\t", -1)
        fail!("malformed tagged output for #{tag}") unless fields.size == width
        fields
      end
    end

    def normalize_type(type)
      type.gsub(/\s+/, '')
    end

    def safe_native_path(path, store)
      real = File.realpath(path)
      root = File.realpath(store)
      fail!("native part path escaped isolated store: #{path}") unless real.start_with?(root + File::SEPARATOR)
      fail!('native part path is not a canonical directory') unless File.directory?(real) && !File.symlink?(path)
      real
    end

    def native_part!(id, table, store, mark_format: 'mrk4')
      schema_tag = marker('schema', id)
      part_tag = marker('part', id)
      sql = "SELECT '#{schema_tag}', name, type FROM system.columns WHERE database='default' AND table='#{table}' ORDER BY position FORMAT TSVRaw;\n" \
        "SELECT '#{part_tag}', table, name, path, part_type, toString(rows), toString(marks) FROM system.parts " \
        "WHERE database='default' AND table='#{table}' AND active ORDER BY name FORMAT TSVRaw;\n"
      result = native("#{id}_schema_part", store, sql)
      fail!("#{id} schema/part query refused") unless result[:classification] == 'success'
      lines = native_lines(result, "#{id} schema/part")
      schemas = tagged(lines, schema_tag, 3).map { |fields| fields.drop(1) }
      actual = schemas.map { |name, type| [name, normalize_type(type)] }
      expected = SCHEMA.map { |name, type| [name, normalize_type(type)] }
      fail!("#{id} native schema differs: #{actual.inspect}") unless actual == expected
      parts = tagged(lines, part_tag, 7)
      fail!("#{id} is not one six-row Compact part with three marks plus EOF") unless
        parts.size == 1 && parts.first.values_at(1, 2, 4, 5, 6) == [table, PART_NAME, 'Compact', '6', '4']
      path = safe_native_path(parts.first.fetch(3), store)
      chosen = "data.#{mark_format}"
      other = mark_format == 'mrk4' ? 'data.mrk3' : 'data.mrk4'
      fail!("#{id} native mark format differs") unless File.file?(File.join(path, chosen)) && !File.exist?(File.join(path, other))
      path
    end

    def check_sql(id, table)
      "SELECT '#{marker('check_begin', id)}' FORMAT TSVRaw;\nCHECK TABLE default.#{table} FORMAT TSV;\n" \
        "SELECT '#{marker('check_end', id)}' FORMAT TSVRaw;\n"
    end

    def check_observation!(id, table, store)
      result = native("#{id}_check", store, check_sql(id, table))
      lines = native_lines(result, "#{id} CHECK")
      first = lines.index(marker('check_begin', id))
      last = lines.index(marker('check_end', id))
      rows = first && last && last > first ? lines[(first + 1)...last] : nil
      {state: 'success', rows: rows, exact_success: rows == ["#{PART_NAME}\t1\t"], invocation: result.fetch(:record)}
    end

    def native_select!(id, table, store, window, fields: {root: true, array: true, tagged: true, pair: true}, strict: true)
      result = native("#{id}_select_#{fields.keys.join('_')}_#{window}", store,
                      native_window_sql(table, window, fields: fields.merge(case_name: id)), allow_server_error: !strict)
      if result[:classification] != 'success'
        fail!("#{id} #{window} SELECT was unexpectedly refused") if strict
        return {state: result[:classification], invocation: result.fetch(:record)}
      end
      lines = native_lines(result, "#{id} #{window} SELECT")
      tag_value = marker('native', id, window)
      if window == 'empty'
        rows = tagged(lines, tag_value, 2)
        exact = rows == [[tag_value, '0']]
        actual = 0
      else
        width = 2 + %i[root array].count { |key| fields.fetch(key, false) } +
          (fields.fetch(:tagged, false) ? 2 : 0) + (fields.fetch(:pair, false) ? 2 : 0)
        rows = tagged(lines, tag_value, width)
        actual = rows.map { |row| row.drop(2).map { |value| parse_hex_json(value, "#{id} #{window}") } }
        expected_rows = ROWS.select { |row| NATIVE_WINDOWS.fetch(window).include?(row.fetch(:pk)) }.map do |row|
          expected_native_columns(row, fields)
        end
        exact = rows.map { |row| row[1] } == NATIVE_WINDOWS.fetch(window).map(&:to_s) && actual == expected_rows
      end
      fail!("#{id} native #{window} SELECT differs from independent literal rows") if strict && !exact
      {state: exact ? 'exact_values' : 'value_mismatch', row_count: actual.is_a?(Integer) ? actual : actual.size,
       rows: window == 'empty' ? [] : actual, invocation: result.fetch(:record)}
    end

    def parse_hex_json(value, label)
      fail!("#{label} output is not hex JSON") unless value.match?(/\A(?:[0-9a-f]{2})*\z/i)
      JSON.parse([value].pack('H*'))
    rescue JSON::ParserError => error
      fail!("#{label} output contains invalid JSON: #{error.message}")
    end

    def expected_native_columns(row, fields)
      result = []
      result << row.fetch(:root_json) if fields.fetch(:root, false)
      result << row.fetch(:array_json) if fields.fetch(:array, false)
      if fields.fetch(:tagged, false)
        result << row.fetch(:tagged_json).map { |item| item.fetch(:doc) }
        result << row.fetch(:tagged_json).map { |item| item.fetch(:tag) }
      end
      if fields.fetch(:pair, false)
        result << row.fetch(:pair_json).fetch(:left)
        result << row.fetch(:pair_json).fetch(:right)
      end
      result
    end

    def native_selects!(id, table, store)
      %w[full middle last empty].to_h do |window|
        [window, native_select!(id, table, store, window)]
      end
    end

    def tree_inventory(path)
      files = []
      total = 0
      Find.find(path) do |entry|
        next if entry == path
        stat = File.lstat(entry)
        fail!("symlink in part tree: #{entry}") if stat.symlink?
        next if stat.directory?
        fail!("non-regular part entry: #{entry}") unless stat.file?
        total += stat.size
        fail!('part file-count bound exceeded') if files.size >= MAX_PART_FILES
        fail!('part byte bound exceeded') if total > MAX_PART_BYTES
        files << {path: entry.delete_prefix(path + File::SEPARATOR), size: stat.size,
                  sha256: Digest::SHA256.file(entry).hexdigest}
      end
      {files: files.sort_by { |item| item.fetch(:path) }, total_bytes: total}
    end

    def parse_columns_substreams!(text, id)
      lines = text.split("\n", -1)
      fail!("#{id} columns_substreams lacks a final newline") unless lines.pop == ''
      fail!("#{id} columns_substreams version differs") unless lines.shift == 'columns substreams version: 1'
      header = /\A(0|[1-9][0-9]*) columns:\z/.match(lines.shift.to_s)
      fail!("#{id} columns_substreams column count is malformed") unless header && header[1].to_i == COLUMN_NAMES.size
      sections = []
      until lines.empty?
        match = /\A(0|[1-9][0-9]*) substreams for column `([a-z][a-z0-9_]*)`:\z/.match(lines.shift)
        fail!("#{id} malformed columns_substreams section") unless match
        count = Integer(match[1], 10)
        fail!("#{id} physical callback count exceeds bound") unless count <= 256 && lines.size >= count
        streams = count.times.map do
          item = /\A\t([A-Za-z0-9_.%]+)\z/.match(lines.shift)
          fail!("#{id} malformed physical stream name") unless item
          item[1]
        end
        fail!("#{id} duplicate stream within column") unless streams.uniq == streams
        sections << [match[2], streams]
        fail!("#{id} too many columns_substreams sections") if sections.size > COLUMN_NAMES.size
      end
      fail!("#{id} stock physical roster column order differs") unless sections.map(&:first) == COLUMN_NAMES
      roster = sections.flat_map { |column, streams| streams.map { |stream| [column, stream] } }
      validate_stock_prefix_roster!(id, sections)
      roster
    end

    def expected_site_prefixes
      SITE_SPECS.flat_map do |site|
        base = site.fetch(:stream_base)
        ["#{base}.object_structure", "#{base}.hot.dynamic_structure", "#{base}.hot.variant_discr_prefix",
         "#{base}.mid.dynamic_structure", "#{base}.mid.variant_discr_prefix"]
      end
    end

    def validate_stock_prefix_roster!(id, sections)
      expected_site_prefixes.each do |expected|
        column = SITE_SPECS.find { |site| expected.start_with?(site.fetch(:stream_base) + '.') }.fetch(:column)
        actual = sections.find { |name, _streams| name == column }.fetch(1)
        fail!("#{id} native stock prefix #{expected} is missing or duplicated") unless actual.count(expected) == 1
      end
      sections.each do |column, streams|
        observed = streams.select { |stream| stream.end_with?('.object_structure', '.dynamic_structure', '.variant_discr_prefix') }
        expected = SITE_SPECS.select { |site| site.fetch(:column) == column }.flat_map do |site|
          base = site.fetch(:stream_base)
          ["#{base}.object_structure", "#{base}.hot.dynamic_structure", "#{base}.hot.variant_discr_prefix",
           "#{base}.mid.dynamic_structure", "#{base}.mid.variant_discr_prefix"]
        end
        fail!("#{id} source-derived Object/Dynamic prefix callback order differs for #{column}: #{observed.inspect}") unless observed == expected
      end
    end

    def capture_inventory!(id, part)
      inventory = tree_inventory(part)
      columns_path = File.join(part, 'columns_substreams.txt')
      fail!("#{id} columns_substreams is missing or symlinked") unless File.file?(columns_path) && !File.symlink?(columns_path)
      text = File.binread(columns_path)
      roster = parse_columns_substreams!(text, id)
      record = {case_name: id, source_part_path: part, inventory: inventory, parsed_stock_roster: roster,
                observed_object_dynamic_shared_paths: source_path_observation(roster),
                columns_substreams_sha256: Digest::SHA256.hexdigest(text)}
      safe_id = id.gsub(/[^A-Za-z0-9_.-]/, '_')
      write_new(File.join(@root, 'source-inventories', "#{safe_id}.columns_substreams.txt"), text)
      write_new(File.join(@root, 'source-inventories', "#{safe_id}.json"), JSON.pretty_generate(record) + "\n")
      %w[data.bin data.mrk4 serialization.json checksums.txt].each do |name|
        source = File.join(part, name)
        fail!("#{id} required stock evidence file #{name} is absent") unless File.file?(source) && !File.symlink?(source)
        write_new(File.join(@root, 'raw-records', "#{safe_id}.#{name}"), File.binread(source))
      end
      record
    end

    def source_path_observation(roster)
      SITE_SPECS.map do |site|
        base = site.fetch(:stream_base)
        entries = roster.select { |column, stream| column == site.fetch(:column) && stream.start_with?(base) }
        {site_key: site.fetch(:key), column: site.fetch(:column), stream_base: base,
         observed_dynamic_streams: entries.map(&:last).grep(/\.(hot|mid)\./),
         observed_shared_streams: entries.map(&:last).grep(/object_shared_data|\.spill(?:\.|$)/)}
      end
    end

    def copy_part!(source, destination, label)
      fail!("#{label} destination already exists") if File.exist?(destination) || File.symlink?(destination)
      FileUtils.cp_r(source, destination, preserve: true)
      fail!("#{label} copied inventory differs") unless tree_inventory(destination) == tree_inventory(source)
      destination
    end

    def helper(label, *arguments, expected_statuses: ['ok'])
      fail!('no prebuilt W269 helper was supplied') unless @helper
      result = @runner.send(:run_process, label, [@helper] + arguments, ''.b, 'crystal-helper',
                            expected_sha: @helper_sha_before, binary_path: @helper)
      record = result.fetch(:record)
      fail!("#{label} helper process failed or exceeded bounds") unless
        !record[:timed_out] && record[:spawn_error].nil? && record[:stdin_write_error].nil? &&
        record[:stdout_read_error].nil? && record[:stderr_read_error].nil? && result[:status] &&
        result[:status].termsig.nil? && result[:classification] == 'success' && result[:status].success? && result[:stderr].empty?
      report = JSON.parse(result[:stdout].dup.force_encoding(Encoding::UTF_8))
      fail!("#{label} helper report envelope differs") unless report.is_a?(Hash) &&
        report.fetch('format') == HELPER_FORMAT && report.fetch('action') == arguments.first &&
        expected_statuses.include?(report.fetch('status'))
      report
    rescue JSON::ParserError => error
      raise Failure, "W269: #{label} helper stdout is invalid JSON: #{error.message}"
    end

    def capture_stock!(layout, mode)
      key = cell_key('mrk4', layout, mode)
      table = table_name(key, 'stock')
      store = store_path(key)
      create = native("#{key}_create_insert", store, stock_sql(layout, mode, table))
      part = native_part!(key, table, store)
      inventory = capture_inventory!(key, part)
      copied = copy_part!(part, File.join(@root, 'parts', "stock_#{key}"), "#{key} stock evidence")
      check = check_observation!(key, table, store)
      fail!("#{key} stock CHECK failed") unless check.fetch(:exact_success)
      selects = native_selects!(key, table, store)
      fail!("#{key} native literal SQL oracle differs") unless selects.values.all? { |value| value.fetch(:state) == 'exact_values' }
      fail!("#{key} native stock source changed during capture") unless tree_inventory(part) == inventory.fetch(:inventory)
      {layout: layout, variant_mode: mode, table: table, store: store, part_path: copied,
       native_source_path: part, create_insert: create.fetch(:record), source_inventory: inventory,
       check: check, native_literal_selects: selects, local_reader_audit: nil}
    end

    def audit_stock_captures!
      @stock.each do |key, stock|
        path = stock.fetch(:part_path)
        before = tree_inventory(path)
        local = helper("#{key}_stock_reader_audit", 'audit', path, stock.fetch(:layout), stock.fetch(:variant_mode))
        fail!("#{key} local stock audit changed its copied part") unless tree_inventory(path) == before
        stock[:local_reader_audit] = validate_helper_report!(
          local, 'mrk4', stock.fetch(:layout), stock.fetch(:variant_mode), key,
          before, stock.fetch(:source_inventory).fetch(:parsed_stock_roster),
        )
      end
    end

    def capture_generated_matrix!
      %w[mrk3 mrk4].product(%w[map map_with_buckets], %w[basic compact]).to_h do |mark_format, layout, mode|
        key = cell_key(mark_format, layout, mode)
        stock = @stock.fetch(cell_key('mrk4', layout, mode))
        [key, capture_generated_cell!(mark_format, layout, mode, key, stock)]
      end
    end

    def capture_generated_cell!(mark_format, layout, mode, key, stock)
      part = File.join(@root, 'parts', "generated_#{key}")
      native_id = "generated_#{key}"
      write = helper("#{key}_writer", 'write-generated', part, mark_format, layout, mode)
      fail!("#{key} generated writer envelope differs") unless write.fetch('part_path') == part &&
        write.fetch('row_count') == ROW_COUNT && write.fetch('mark_format') == mark_format &&
        write.fetch('shared_layout') == layout && write.fetch('variant_discriminator_mode') == (mode == 'compact' ? 1 : 0)
      inventory = tree_inventory(part)
      audit = helper("#{key}_reader_audit", 'audit', part, layout, mode)
      local = validate_helper_report!(audit, mark_format, layout, mode, key, inventory,
                                      stock.fetch(:source_inventory).fetch(:parsed_stock_roster))
      checksum = helper("#{key}_data_checksum", 'verify-checksum', part, 'data.bin', expected_statuses: ['accepted'])
      fail!("#{key} generated data.bin checksum mismatch") unless checksum.fetch('file_hash_matches')
      generated_inventory = record_generated_inventory!(key, part, mark_format, inventory, write, audit)

      target = create_native_target!(key, layout, mode, mark_format)
      attach = attach_copy!(key, part, target)
      fail!("#{key} native ATTACH refused") unless attach.fetch(:state) == 'success'
      active = native_part!("#{key}_attached", target.fetch(:table), target.fetch(:store), mark_format: mark_format)
      active_inventory = tree_inventory(active)
      sidecar = validate_attached_inventory!(key, active, active_inventory, generated_inventory.fetch(:inventory))
      check = check_observation!(native_id, target.fetch(:table), target.fetch(:store))
      fail!("#{key} native CHECK did not report one healthy part") unless check.fetch(:exact_success)
      selects = native_selects!(native_id, target.fetch(:table), target.fetch(:store))
      fail!("#{key} native literal values differ") unless selects.values.all? { |value| value.fetch(:state) == 'exact_values' }
      fail!("#{key} active part changed during CHECK/SELECT") unless tree_inventory(active) == active_inventory
      fail!("#{key} generated source was changed by ATTACH/read") unless tree_inventory(part) == generated_inventory.fetch(:inventory)
      {mark_format: mark_format, layout: layout, variant_mode: mode, part_path: part,
       write_report: write, source_inventory: generated_inventory, local_reader_audit: local,
       data_bin_checksum: checksum, native_target: target, native_attach: attach,
       active_native_part: {path: active, inventory: active_inventory, native_owned_sidecar: sidecar},
       native_check: check, native_literal_selects: selects}
    end

    def validate_helper_report!(report, mark_format, layout, mode, label, inventory, source_roster)
      fail!("#{label} helper audit status differs") unless report.fetch('status') == 'ok'
      fail!("#{label} row/mark grid differs") unless report.fetch('mark_format') == mark_format &&
        report.fetch('row_count') == ROW_COUNT && report.fetch('granule_count') == MARK_COUNT &&
        report.fetch('mark_rows') == [ROWS_PER_MARK] * MARK_COUNT
      physical = report.fetch('physical_roster').map { |entry| [entry.fetch('column'), entry.fetch('stream')] }
      expected_roster = if mark_format == 'mrk4'
                          source_roster
                        else
                          COLUMN_NAMES.map { |name| [name, ''] }
                        end
      fail!("#{label} candidate physical roster differs from independently captured stock/MRK3 contract") unless physical == expected_roster
      tape = report.fetch('physical_mark_tape')
      data_file = inventory.fetch(:files).find { |entry| entry.fetch(:path) == 'data.bin' }
      mark_name = "data.#{mark_format}"
      mark_file = inventory.fetch(:files).find { |entry| entry.fetch(:path) == mark_name }
      other_mark = mark_format == 'mrk4' ? 'data.mrk3' : 'data.mrk4'
      fail!("#{label} mark/data inventory differs") unless data_file && mark_file && inventory.fetch(:files).none? { |entry| entry.fetch(:path) == other_mark }
      slots = physical.size
      width = slots * 16 + 8
      fail!("#{label} mark record dimensions differ") unless tape.fetch('file') == mark_name &&
        tape.fetch('slot_count') == slots && tape.fetch('record_width') == width &&
        tape.fetch('byte_size') == width * (MARK_COUNT + 1) && tape.fetch('records').size == MARK_COUNT + 1 &&
        tape.fetch('records').map { |record| record.fetch('row_count') } == MARK_ROWS_WITH_EOF &&
        tape.fetch('byte_size') == mark_file.fetch(:size) && tape.fetch('compressed_size') == data_file.fetch(:size) &&
        tape.fetch('raw_size').positive?
      tape.fetch('records').each_with_index do |record, mark|
        fail!("#{label} mark #{mark} slot count/order differs") unless record.fetch('mark') == mark &&
          record.fetch('pairs').size == slots && record.fetch('pairs').map { |pair| pair.fetch('slot') } == (0...slots).to_a
        record.fetch('pairs').each do |pair|
          fail!("#{label} mark coordinate escaped file bounds") unless pair.fetch('compressed_offset').between?(0, tape.fetch('compressed_size')) &&
            pair.fetch('logical_position').between?(0, tape.fetch('raw_size')) && pair.fetch('decompressed_offset') >= 0
        end
      end
      tape.fetch('records').each_cons(2) do |left, right|
        slots.times do |slot|
          fail!("#{label} slot #{slot} mark positions move backwards") if
            left.fetch('pairs').fetch(slot).fetch('logical_position') > right.fetch('pairs').fetch(slot).fetch('logical_position')
        end
      end
      fail!("#{label} terminal record is not all-slot EOF") unless tape.fetch('records').last.fetch('pairs').all? do |pair|
        pair.fetch('compressed_offset') == tape.fetch('compressed_size') && pair.fetch('decompressed_offset').zero? &&
          pair.fetch('logical_position') == tape.fetch('raw_size')
      end
      raw_hex = report.fetch('raw_data_hex')
      fail!("#{label} raw data census is malformed") unless raw_hex.match?(/\A(?:[0-9a-f]{2})*\z/) && raw_hex.bytesize == tape.fetch('raw_size') * 2
      validate_helper_shards!(report, label, mark_format, expected_roster, raw_hex)
      validate_windows!(report.fetch('windows'), label)
      validate_metadata!(report.fetch('metadata'), label)
      if mark_format == 'mrk4'
        validate_prefixes!(report.fetch('prefix_observation'), label, layout, mode, source_roster)
      else
        fail!("#{label} MRK3 callback audit overstates named streams") unless
          report.fetch('prefix_observation').fetch('state') == 'mrk3_named_callbacks_not_persisted'
      end
      {physical_roster: physical, mark_tape: tape, observed_prefixes: report.fetch('prefix_observation'),
       local_windows: report.fetch('windows'), metadata: report.fetch('metadata')}
    end

    def validate_helper_shards!(report, label, mark_format, expected_roster, raw_hex)
      shards = report.fetch('callback_shards')
      slots = expected_roster.size
      raw = [raw_hex].pack('H*')
      fail!("#{label} callback shard count differs") unless shards.size == MARK_COUNT * slots
      expected_order = MARK_COUNT.times.flat_map do |mark|
        expected_roster.each_index.map { |slot| [mark, slot] }
      end
      actual_order = shards.map { |shard| [shard.fetch('mark'), shard.fetch('slot')] }
      fail!("#{label} callback shards are not in physical mark/callback order") unless actual_order == expected_order
      MARK_COUNT.times do |mark|
        per_mark = shards.select { |shard| shard.fetch('mark') == mark }
        fail!("#{label} mark #{mark} callback roster differs") unless per_mark.map { |shard| [shard.fetch('column'), shard.fetch('stream')] } == expected_roster
        fail!("#{label} mark #{mark} callback ordinals differ") unless per_mark.map { |shard| shard.fetch('slot') } == (0...slots).to_a
        per_mark.each do |shard|
          bytes = shard.fetch('bytes_hex')
          start = shard.fetch('logical_start')
          count = shard.fetch('byte_count')
          finish = shard.fetch('logical_end')
          fail!("#{label} callback byte encoding/bounds differ") unless bytes.match?(/\A(?:[0-9a-f]{2})*\z/) &&
            bytes.bytesize == count * 2 && start >= 0 && finish >= start && finish <= raw.bytesize && finish - start == count
          fail!("#{label} callback bytes differ from raw data.bin") unless raw.byteslice(start, count) == [bytes].pack('H*')
        end
      end
      ordered = shards.sort_by { |shard| [shard.fetch('mark'), shard.fetch('slot')] }
      fail!("#{label} named callback spans do not partition raw data.bin") unless ordered.first.fetch('logical_start').zero? &&
        ordered.last.fetch('logical_end') == raw.bytesize && ordered.each_cons(2).all? { |left, right| left.fetch('logical_end') == right.fetch('logical_start') }
      true
    end

    def validate_windows!(windows, label)
      expected_columns = COLUMN_NAMES.drop(1).sort
      fail!("#{label} local window set differs") unless windows.keys.sort == LOCAL_WINDOWS.keys.sort
      LOCAL_WINDOWS.each do |name, pks|
        actual = windows.fetch(name)
        fail!("#{label} #{name} local column inventory differs") unless actual.keys.sort == expected_columns
        expected_rows = ROWS.select { |row| pks.include?(row.fetch(:pk)) }
        expected_columns.each do |column|
          expected = expected_rows.map { |row| literal_json(row.fetch(column.to_sym)) }
          fail!("#{label} #{name} local #{column} reader differs from independent literals") unless actual.fetch(column) == expected
        end
      end
    end

    def validate_literal_column_keys!
      expected_columns = COLUMN_NAMES.drop(1)
      ROWS.each_with_index do |row, index|
        missing = expected_columns.reject { |column| row.key?(column.to_sym) }
        fail!("W269 literal row #{index + 1} is missing schema columns #{missing.join(', ')}") unless missing.empty?
      end
      true
    end

    def literal_json(value)
      case value
      when Hash
        value.to_h { |key, child| [key.to_s, literal_json(child)] }
      when Array
        value.map { |child| literal_json(child) }
      else
        value
      end
    end

    def census_report
      SITE_SPECS.map do |site|
        docs = site_documents(site.fetch(:key))
        paths = %w[hot mid].to_h do |path|
          counts = Hash.new(0)
          docs.each do |document|
            type = document.fetch(path).class == String ? 'String' : 'Bool'
            counts[type] += 1
          end
          dominant = counts.max_by { |type, count| [count, type] }.first
          shared = counts.reject { |type, _count| type == dominant }
          [path, {ordinary_type: dominant, ordinary_count: counts.fetch(dominant),
                  shared_type_counts: shared, shared_variant_count: shared.values.sum}]
        end
        {site_key: site.fetch(:key), object_count: docs.size, shared_path_counts: {'spill' => docs.count { |d| d.key?('spill') }}, dynamic_paths: paths}
      end
    end

    def site_documents(key)
      case key
      when 'root' then ROWS.map { |row| row.fetch(:root_json) }
      when 'root/array[0]' then ROWS.flat_map { |row| row.fetch(:array_json) }
      when 'root/array[0]/tuple[0]' then ROWS.flat_map { |row| row.fetch(:tagged_json).map { |item| item.fetch(:doc) } }
      when 'root/tuple[0]' then ROWS.map { |row| row.fetch(:pair_json).fetch(:left) }
      when 'root/tuple[1]' then ROWS.map { |row| row.fetch(:pair_json).fetch(:right) }
      else fail!("unknown W269 site key #{key}")
      end
    end

    def validate_prefixes!(observation, label, layout, mode, source_roster)
      fail!("#{label} named prefix observation state differs") unless observation.fetch('state') == 'decoded_named_prefixes'
      expected_shared = layout == 'map' ? 0 : 1
      expected_buckets = layout == 'map' ? 1 : 2
      expected_streams = source_roster.select { |_column, stream| stream.end_with?('.object_structure', '.dynamic_structure', '.variant_discr_prefix') }
      records = {
        'object_structures' => observation.fetch('object_structures'),
        'dynamic_structures' => observation.fetch('dynamic_structures'),
        'variant_prefixes' => observation.fetch('variant_prefixes'),
      }
      expected_types = {
        'object_structures' => '.object_structure',
        'dynamic_structures' => '.dynamic_structure',
        'variant_prefixes' => '.variant_discr_prefix',
      }
      records.each do |name, entries|
        suffix = expected_types.fetch(name)
        expected = MARK_COUNT.times.flat_map do |mark|
          expected_streams.select { |_column, stream| stream.end_with?(suffix) }.map { |column, stream| [column, mark, stream] }
        end
        actual = entries.map { |entry| [entry.fetch('column'), entry.fetch('mark'), entry.fetch('stream')] }
        fail!("#{label} #{name} prefixes are missing, duplicated, misassociated, or out of callback order") unless actual == expected
      end
      census = census_report.to_h { |item| [item.fetch(:site_key), item] }
      object_entries = records.fetch('object_structures')
      dynamic_entries = records.fetch('dynamic_structures')
      object_entries.each do |entry|
        site = SITE_SPECS.find { |item| item.fetch(:stream_base) == entry.fetch('stream').delete_suffix('.object_structure') }
        fail!("#{label} unknown Object structure prefix") unless site
        expected = census.fetch(site.fetch(:key))
        fail!("#{label} Object V3/shared layout prefix differs") unless entry.fetch('version') == 4 &&
          entry.fetch('dynamic_paths') == %w[hot mid] && entry.fetch('shared_data_version') == expected_shared &&
          entry.fetch('bucket_count') == expected_buckets
        validate_object_stats!(entry, expected, label)
      end
      dynamic_entries.each do |entry|
        suffix = entry.fetch('stream').delete_suffix('.dynamic_structure')
        site = SITE_SPECS.find { |item| entry.fetch('stream').start_with?(item.fetch(:stream_base) + '.') }
        fail!("#{label} unknown Dynamic structure prefix") unless site
        path = suffix.delete_prefix(site.fetch(:stream_base) + '.')
        fail!("#{label} unknown JSON Dynamic path") unless %w[hot mid].include?(path)
        expected = census.fetch(site.fetch(:key)).fetch(:dynamic_paths).fetch(path)
        fail!("#{label} Dynamic wire/ordinary roster differs") unless entry.fetch('version') == 4 &&
          entry.fetch('ordinary_types') == [expected.fetch(:ordinary_type)]
        validate_dynamic_stats!(entry, expected, label)
      end
      expected_mode = mode == 'compact' ? 1 : 0
      records.fetch('variant_prefixes').each do |entry|
        fail!("#{label} Variant discriminator mode differs") unless entry.fetch('mode') == expected_mode &&
          entry.fetch('prefix_hex') == (expected_mode.zero? ? '0000000000000000' : '0100000000000000')
      end
      true
    end

    def validate_object_stats!(entry, expected, label)
      mark = entry.fetch('mark')
      flag = mark.zero? ? 1 : 0
      fail!("#{label} Object statistics flag differs at mark #{mark}") unless entry.fetch('statistics_flag') == flag
      if mark.zero?
        stats = entry.fetch('statistics') || fail!("#{label} first Object prefix lacks six-row block statistics")
        shared = statistics_shared_map(stats, label)
        fail!("#{label} first Object full-block statistics differ") unless
          stats.fetch('counts') == [expected.fetch(:object_count)] * 2 && shared == expected.fetch(:shared_path_counts)
      else
        fail!("#{label} later Object prefix is not statistics-empty") unless entry.fetch('statistics').nil?
      end
    end

    def validate_dynamic_stats!(entry, expected, label)
      mark = entry.fetch('mark')
      flag = mark.zero? ? 1 : 0
      fail!("#{label} Dynamic statistics flag differs at mark #{mark}") unless entry.fetch('statistics_flag') == flag
      if mark.zero?
        stats = entry.fetch('statistics') || fail!("#{label} first Dynamic prefix lacks block statistics")
        names = ['SharedVariant', expected.fetch(:ordinary_type)].sort
        expected_counts = names.map do |name|
          name == 'SharedVariant' ? expected.fetch(:shared_variant_count) : expected.fetch(:ordinary_count)
        end
        shared = statistics_shared_map(stats, label)
        fail!("#{label} first Dynamic census differs from six-row SQL literals") unless
          stats.fetch('counts') == expected_counts && shared == expected.fetch(:shared_type_counts)
      else
        fail!("#{label} later Dynamic prefix is not statistics-empty") unless entry.fetch('statistics').nil?
      end
    end

    def decode_name_hex(hex)
      fail!('statistics shared path/type name is not lowercase hex') unless hex.match?(/\A(?:[0-9a-f]{2})*\z/)
      [hex].pack('H*').force_encoding(Encoding::UTF_8).tap do |name|
        fail!('statistics name is not valid UTF-8') unless name.valid_encoding?
      end
    end

    def statistics_shared_map(stats, label)
      entries = stats.fetch('shared')
      fail!("#{label} shared statistics are not an array") unless entries.is_a?(Array)
      pairs = entries.map do |item|
        fail!("#{label} shared statistic is not an object") unless item.is_a?(Hash)
        name = decode_name_hex(item.fetch('name_hex'))
        count = item.fetch('count')
        fail!("#{label} shared statistic count is not a nonnegative integer") unless count.is_a?(Integer) && count >= 0
        [name, count]
      end
      names = pairs.map(&:first)
      fail!("#{label} shared statistics contain duplicate names") unless names.uniq.size == names.size
      pairs.to_h
    end

    def validate_metadata!(metadata, label)
      fail!("#{label} serialization.json is not an object") unless metadata.is_a?(Hash)
      fail!("#{label} type-version metadata differs") unless metadata.fetch('types_serialization_versions') == {'string' => 0}
      fail!("#{label} nested serialization-version propagation is false") unless metadata.fetch('propagate_types_serialization_versions_to_nested_types') == true
      true
    end

    def record_generated_inventory!(key, part, mark_format, inventory, write, audit)
      required = %w[data.bin]
      required << "data.#{mark_format}"
      paths = inventory.fetch(:files).map { |entry| entry.fetch(:path) }
      fail!("#{key} generated part lacks required data/mark files") unless (required - paths).empty?
      record = {case_name: key, source_part_path: part, mark_format: mark_format, inventory: inventory,
                writer_report: write, audit_report: audit}
      safe = key.gsub(/[^A-Za-z0-9_.-]/, '_')
      write_new(File.join(@root, 'source-inventories', "generated_#{safe}.json"), JSON.pretty_generate(record) + "\n")
      required.each { |name| write_new(File.join(@root, 'raw-records', "generated_#{safe}.#{name}"), File.binread(File.join(part, name))) }
      record
    end

    def create_native_target!(key, layout, mode, mark_format)
      store = store_path("target_#{key}")
      table = table_name(key, 'target')
      sql = "CREATE TABLE default.#{table} (#{declarations}) ENGINE=MergeTree ORDER BY pk SETTINGS #{settings(layout, mode, mark_format: mark_format)};\n" \
        "SELECT '#{marker('path', key)}', arrayElement(data_paths, 1) FROM system.tables WHERE database='default' AND name='#{table}' FORMAT TSVRaw;\n"
      result = native("#{key}_target_create", store, sql)
      paths = tagged(native_lines(result, "#{key} target CREATE"), marker('path', key), 2)
      fail!("#{key} native target data path is not unique") unless paths.size == 1 && !paths.first[1].empty?
      {table: table, store: store, data_path: safe_native_path(paths.first[1], store), create_invocation: result.fetch(:record)}
    end

    def attach_copy!(key, source, target)
      source_inventory = tree_inventory(source)
      @runner.send(:attach_part!, source, target.fetch(:data_path))
      detached = File.join(target.fetch(:data_path), 'detached', PART_NAME)
      copied = tree_inventory(detached)
      fail!("#{key} detached copy differs from source") unless copied == source_inventory
      result = native("#{key}_attach", target.fetch(:store), "ALTER TABLE default.#{target.fetch(:table)} ATTACH PART '#{PART_NAME}';\n")
      {state: result[:classification], invocation: result.fetch(:record), source_inventory: source_inventory, detached_inventory: copied}
    end

    def validate_attached_inventory!(key, active_part, active_inventory, source_inventory)
      source = source_inventory.fetch(:files).to_h { |entry| [entry.fetch(:path), entry] }
      active = active_inventory.fetch(:files).to_h { |entry| [entry.fetch(:path), entry] }
      missing = source.keys - active.keys
      extra = active.keys - source.keys
      fail!("#{key} ATTACH removed source files #{missing.inspect}") unless missing.empty?
      fail!("#{key} ATTACH added unexpected files #{extra.inspect}") unless extra == ['invalidated_system_columns.txt']
      changed = source.keys.sort.select { |name| source[name] != active[name] }
      fail!("#{key} ATTACH changed generated source files #{changed.inspect}") unless changed.empty?
      path = File.join(active_part, 'invalidated_system_columns.txt')
      bytes = File.binread(path)
      text = bytes.dup.force_encoding(Encoding::UTF_8)
      lines = text.split("\n", -1)
      newline = lines.pop == ''
      fail!("#{key} ATTACH invalidation sidecar differs") unless text.valid_encoding? && newline && lines.sort == %w[_block_number _block_offset] && lines.size == 2
      fail!("#{key} ATTACH inventory byte sum differs") unless active_inventory.fetch(:total_bytes) == source_inventory.fetch(:total_bytes) + bytes.bytesize
      {path: 'invalidated_system_columns.txt', contents: text, size: bytes.bytesize, sha256: Digest::SHA256.hexdigest(bytes)}
    end

    def cell_key(mark_format, layout, mode)
      [mark_format, layout, mode].join('_')
    end

    def validate_native_label_plan!
      stock_ids = %w[map map_with_buckets].product(%w[basic compact]).map do |layout, mode|
        cell_key('mrk4', layout, mode)
      end
      generated_ids = %w[mrk3 mrk4].product(%w[map map_with_buckets], %w[basic compact]).map do |mark_format, layout, mode|
        "generated_#{cell_key(mark_format, layout, mode)}"
      end
      labels_for = lambda do |id|
        ["#{id}_check"] + %w[full middle last empty].map do |window|
          "#{id}_select_root_array_tagged_pair_#{window}"
        end
      end
      stock_labels = stock_ids.flat_map { |id| labels_for.call(id) }
      generated_labels = generated_ids.flat_map { |id| labels_for.call(id) }
      fail!('W269 stock native invocation label plan is not unique') unless stock_labels.size == 20 && stock_labels.uniq.size == stock_labels.size
      fail!('W269 generated native invocation label plan is not unique') unless generated_labels.size == 40 && generated_labels.uniq.size == generated_labels.size
      fail!('W269 stock/generated native invocation label namespaces overlap') unless (stock_labels & generated_labels).empty?
      true
    end

    def capture_generated_source_inventory!(key, part, mark_format, write, audit)
      record_generated_inventory!(key, part, mark_format, tree_inventory(part), write, audit)
    end

    def qualify_copy_mutant!(source_cell)
      source = source_cell.fetch(:part_path)
      source_before = tree_inventory(source)
      mutation_path = File.join(@root, 'parts', 'poison_resealed_middle')
      mutation = helper('poison_resealed_copy', 'copy-mutant', 'resealed', source, mutation_path, 'tagged_json', '1')
      mutated = tree_inventory(mutation_path)
      source_map = source_before.fetch(:files).to_h { |entry| [entry.fetch(:path), entry] }
      mutated_map = mutated.fetch(:files).to_h { |entry| [entry.fetch(:path), entry] }
      changed = (source_map.keys | mutated_map.keys).sort.select { |name| source_map[name] != mutated_map[name] }
      fail!('resealed Object-prefix mutation changed files outside data.bin/checksums.txt') unless changed == %w[checksums.txt data.bin]
      fail!('mutant changed mark bytes/size or data.bin size') unless source_map.fetch('data.mrk4') == mutated_map.fetch('data.mrk4') &&
        source_map.fetch('data.bin').fetch(:size) == mutated_map.fetch('data.bin').fetch(:size)
      fail!('mutant report is not the exact one-byte Object 4-to-3 control') unless mutation.fetch('stream') == 'tagged_json%2Edoc.object_structure' &&
        mutation.fetch('mark') == 1 && mutation.fetch('version_before') == 4 && mutation.fetch('version_after') == 3 &&
        mutation.fetch('raw_changed_offsets').size == 1 && mutation.fetch('compressed_size_before') == mutation.fetch('compressed_size_after') &&
        mutation.fetch('checksums_resealed') == true
      local_mid = helper('poison_local_tagged_middle', 'read', mutation_path, 'tagged_json', '1', '1', expected_statuses: ['rejected'])
      fail!('local selected tagged middle did not reject resealed Object wire-version mutant') unless local_mid.fetch('status') == 'rejected'
      root_middle = helper('poison_local_root_middle', 'read', mutation_path, 'root_json', '1', '1', expected_statuses: ['accepted'])
      fail!('local root-column positive control differs') unless root_middle.fetch('status') == 'accepted' &&
        root_middle.fetch('signatures') == LOCAL_WINDOWS.fetch('middle').map { |pk| literal_json(ROWS.fetch(pk - 1).fetch(:root_json)) }
      local_same_column = {
        tagged_last_mark: helper('poison_local_tagged_last_mark', 'read', mutation_path, 'tagged_json', '2', '1', expected_statuses: %w[accepted rejected]),
        tagged_empty: helper('poison_local_tagged_empty', 'read', mutation_path, 'tagged_json', '3', '0', expected_statuses: %w[accepted rejected]),
      }
      local_same_column.each do |name, observation|
        next if observation.fetch('status') == 'rejected'
        expected_pks = name == :tagged_last_mark ? LOCAL_WINDOWS.fetch('last_mark') : []
        expected = ROWS.select { |row| expected_pks.include?(row.fetch(:pk)) }.map { |row| literal_json(row.fetch(:tagged_json)) }
        fail!("local #{name} accepted values differ") unless observation.fetch('signatures') == expected
      end
      fail!('local mutant readers changed the resealed copy') unless tree_inventory(mutation_path) == mutated

      target = create_native_target!('poison_resealed', 'map_with_buckets', 'compact', 'mrk4')
      attach = attach_copy!('poison_resealed', mutation_path, target)
      fail!('native ATTACH refused resealed mutant') unless attach.fetch(:state) == 'success'
      active = native_part!('poison_resealed_attached', target.fetch(:table), target.fetch(:store))
      active_inventory = tree_inventory(active)
      check = check_observation!('poison_resealed', target.fetch(:table), target.fetch(:store))
      fail!('native CHECK is not the expected separate healthy structural observation') unless check.fetch(:exact_success)
      bad = native_select!('poison_resealed', target.fetch(:table), target.fetch(:store), 'middle',
                           fields: {tagged: true}, strict: false)
      fail!('native selected tagged middle did not semantically reject the resealed malformed prefix') unless bad.fetch(:state) == 'server_exception'
      native_controls = {
        pk_middle: native_select!('poison_resealed', target.fetch(:table), target.fetch(:store), 'middle', fields: {}, strict: true),
        root_middle: native_select!('poison_resealed', target.fetch(:table), target.fetch(:store), 'middle', fields: {root: true}, strict: true),
        tagged_last_observation: native_select!('poison_resealed', target.fetch(:table), target.fetch(:store), 'last', fields: {tagged: true}, strict: false),
        tagged_empty_observation: native_select!('poison_resealed', target.fetch(:table), target.fetch(:store), 'empty', fields: {tagged: true}, strict: false),
      }
      native_controls.values_at(:tagged_last_observation, :tagged_empty_observation).each do |observation|
        fail!('same-column mutant control was neither exact nor a native server exception') unless
          %w[exact_values server_exception].include?(observation.fetch(:state))
      end
      fail!('native CHECK/SELECT changed the active mutant part') unless tree_inventory(active) == active_inventory
      fail!('native CHECK/SELECT changed the resealed mutant source copy') unless tree_inventory(mutation_path) == mutated
      fail!('source generated part changed during copy-only mutant experiment') unless tree_inventory(source) == source_before
      {mutation: mutation, source_inventory: source_before, mutant_inventory: mutated, changed_files: changed,
       local_selected_rejection: local_mid, local_root_positive_control: root_middle,
       local_same_column_controls: local_same_column, native_target: target, native_attach: attach,
       native_check_nonsemantic: check, native_selected_rejection: bad, native_controls: native_controls,
       active_part_path: active}
    end

    def validate_pins!
      fail!('ClickHouse executable SHA changed during capture') unless binary_sha == BINARY_SHA256
      fail!('prebuilt helper SHA changed during capture') if @helper && helper_sha != @helper_sha_before
      @source_hashes_before.each { |path, expected| fail!("probe source changed during capture: #{path}") unless sha(path) == expected }
      @upstream_hashes.each do |relative, expected|
        fail!("pinned upstream source changed during capture: #{relative}") unless sha(File.join(SOURCE_ROOT, relative)) == expected
      end
      true
    end

    def render_summary(summary)
      <<~MD
        # W269 stock-first compact JSON/Object witness

        - Status: `#{summary.fetch(:status)}`.
        - Native pin: ClickHouse #{W241::VERSION} / `#{W241::BUILD}` / SHA-256 `#{BINARY_SHA256}`.
        - Source pin: `#{SOURCE_REVISION}` at `#{SOURCE_ROOT}`; its serialization sources are hashed independently.
        - Witness: six literal rows, three two-row marks plus EOF; root/Array(JSON)/Array(Tuple(JSON, UInt8))/Tuple(JSON, JSON); Object V3, Dynamic V3, MAP or MAP_WITH_BUCKETS, BASIC or COMPACT discriminators.
        - Array(JSON) rows 3 and 4 contain no JSON children, while tagged-array and tuple sites remain populated.
        - Native stock callback rosters are captured and parsed before generated writer audits. Expected JSON metadata is fixed String v0 plus nested propagation; no JSON/Object/Dynamic version metadata is admitted.
        - Native full/middle/last-row/empty SQL windows are compared to literal Ruby input; the empty SQL case is cardinality-only. Helper last_mark is separately rows 5 and 6.
        - CHECK and selected-value reads are separate observations. No granule-only IO claim is made.
        - Evidence: `#{@root}`.
      MD
    end

    def persist_inconclusive(error)
      path = File.join(@root, 'summary.json')
      return if File.exist?(path)
      summary = {format: FORMAT, status: 'inconclusive', fatal_error: "#{error.class}: #{error.message}",
                 evidence_root: @root, invocations: @invocations}
      write_new(path, JSON.pretty_generate(summary) + "\n")
    rescue StandardError => summary_error
      warn "W269 inconclusive summary persistence failed: #{summary_error.class}: #{summary_error.message}"
    end
  end

  def self.main
    options = {binary: BINARY}
    selected = nil
    OptionParser.new do |parser|
      parser.banner = 'Usage: ruby scripts/probe_compact_part_writer_w269.rb (--stock-only | --generated-matrix) --evidence-root EMPTY_DIRECT_CHILD_OF_PRIVATE_TMP [--crystal-helper PREBUILT_HELPER] [--clickhouse PINNED_CLICKHOUSE]'
      parser.on('--stock-only', 'Capture four stock-native layout/discriminator cells; helper is optional') do
        abort 'W269: select exactly one run mode' if selected
        selected = :stock
      end
      parser.on('--generated-matrix', 'Capture stock first, then eight MRK3/MRK4 generated cells; requires helper') do
        abort 'W269: select exactly one run mode' if selected
        selected = :generated
      end
      parser.on('--clickhouse PATH', 'Pinned native ClickHouse executable') { |value| options[:binary] = value }
      parser.on('--crystal-helper PATH', 'Optional prebuilt W269 helper; this driver never compiles it') { |value| options[:helper] = value }
      parser.on('--evidence-root PATH', 'Existing empty direct child of /private/tmp') { |value| options[:evidence_root] = value }
    end.parse!
    abort 'W269: choose a mode and provide --evidence-root' unless selected && options[:evidence_root]
    abort 'W269: --generated-matrix requires --crystal-helper' if selected == :generated && !options[:helper]
    probe = Probe.new(binary: options[:binary], helper: options[:helper], evidence_root: options[:evidence_root],
                      generated_matrix: selected == :generated)
    exit(probe.run ? 0 : 1)
  rescue StandardError => error
    warn "W269 runner error: #{error.class}: #{error.message}"
    exit 1
  end
end

if $PROGRAM_NAME == __FILE__
  ProbeCompactPartWriterW269.main
end
